1	import { safeErrorMessage } from '@/lib/safe-error-message';
2	import { Pool, neonConfig } from '@neondatabase/serverless';
3	import { drizzle } from 'drizzle-orm/neon-serverless';
4	import type { NeonDatabase } from 'drizzle-orm/neon-serverless';
5	import ws from 'ws';
6	import * as schema from './schema';
7	
8	// Required for Node.js environments (dev server, scripts) — Neon's
9	// serverless driver uses WebSockets under the hood; in browsers/edge
10	// runtimes the global WebSocket is available, but in Node we must
11	// provide one explicitly.
12	neonConfig.webSocketConstructor = ws;
13	
14	type DbSchema = typeof schema;
15	
16	let _db: NeonDatabase<DbSchema> | undefined;
17	
18	function getDb(): NeonDatabase<DbSchema> {
19	  if (_db) return _db;
20	  if (!process.env.DATABASE_URL) {
21	    throw new Error('DATABASE_URL must be set in environment variables');
22	  }
23	  // Keep pool small and short-lived for serverless (Vercel): each Lambda /
24	  // Edge invocation may spin up its own process, so a large pool would risk
25	  // exhausting Neon's connection limit across concurrent invocations.
26	  // biome-ignore lint/style/noNonNullAssertion: validated above
27	  let connStr = process.env.DATABASE_URL!;
28	  if (!connStr.includes('application_name=')) {
29	    connStr += `${connStr.includes('?') ? '&' : '?'}application_name=hilo-figma-atos`;
30	  }
31	  const pool = new Pool({
32	    connectionString: connStr,
33	    max: 8,
34	    idleTimeoutMillis: 10_000,
35	    connectionTimeoutMillis: 30_000,
36	  });
37	
38	  // Prevent idle connection failures from becoming unhandled fatal exceptions.
39	  // Without this listener, if a pooled WebSocket connection drops unexpectedly
40	  // (e.g. Neon compute restart, network blip), Node.js converts the unhandled
41	  // 'error' event into an uncaught exception that Sentry captures at fatal
42	  // level — producing noise like "DB_CONNECTIVITY_FAILURE: [object Object]".
43	  pool.on('error', (err: unknown) => {
44	    const msg = safeErrorMessage(err);
45	    console.error('[db] Pool client error (handled):', msg);
46	  });
47	
48	  _db = drizzle(pool, { schema });
49	  return _db;
50	}
51	
52	/**
53	 * Lazy singleton Drizzle client backed by a Neon WebSocket pool.
54	 * Supports full transactions (db.transaction()) unlike the HTTP driver.
55	 * The DATABASE_URL check is deferred until the first actual query so that
56	 * Next.js can evaluate the module at build time without requiring the env
57	 * var to be present in the build environment.
58	 */
59	export const db: NeonDatabase<DbSchema> = new Proxy(
60	  {} as NeonDatabase<DbSchema>,
61	  {
62	    get(_target, prop: string | symbol) {
63	      return getDb()[prop as keyof NeonDatabase<DbSchema>];
64	    },
65	  },
66	);
67	
68	/**
69	 * The transaction handle passed to a `withTransaction` callback. Same query
70	 * builder surface as `db` (select/insert/update/delete), scoped to the tx.
71	 */
72	export type DbTransaction = Parameters<
73	  NeonDatabase<DbSchema>['transaction']
74	>[0] extends (tx: infer Tx) => unknown
75	  ? Tx
76	  : never;
77	
78	/**
79	 * Either the pooled `db` connection or an open transaction handle. Repository
80	 * reads/writes accept this (defaulting to `db`) so a caller can thread a single
81	 * transaction — with a row lock — through a multi-step read-modify-write.
82	 */
83	export type DbExecutor = NeonDatabase<DbSchema> | DbTransaction;
84	
85	/**
86	 * Execute a callback inside a database transaction.
87	 * Delegates to `db.transaction()` — extracted so callers can import a
88	 * single helper instead of depending on the Drizzle `.transaction` method.
89	 */
90	export function withTransaction<T>(
91	  fn: (tx: DbTransaction) => Promise<T>,
92	): Promise<T> {
93	  // DbTransaction is defined as exactly db.transaction()'s callback parameter
94	  // type, so this is assignable with no cast.
95	  return db.transaction(fn);
96	}
