1	import { sql } from 'drizzle-orm';
2	import { db } from './db';
3	
4	/**
5	 * Set the tenant context for the current database session.
6	 * Must be called before any tenant-scoped query when RLS is enabled.
7	 *
8	 * @param flightSchoolId - The UUID of the flight school to scope queries to.
9	 * @param isSuperAdmin - If true, bypasses RLS restrictions (use for admin operations).
10	 */
11	export async function setTenantContext(
12	  flightSchoolId: string,
13	  isSuperAdmin = false,
14	): Promise<void> {
15	  await db.execute(
16	    sql`SELECT set_config('app.flight_school_id', ${flightSchoolId}, true)`,
17	  );
18	  await db.execute(
19	    sql`SELECT set_config('app.is_superadmin', ${isSuperAdmin ? 'true' : 'false'}, true)`,
20	  );
21	}
22	
23	/**
24	 * Clear the tenant context. Call after completing tenant-scoped operations
25	 * to prevent context leaking to subsequent queries in the same connection.
26	 */
27	export async function clearTenantContext(): Promise<void> {
28	  await db.execute(sql`SELECT set_config('app.flight_school_id', '', true)`);
29	  await db.execute(sql`SELECT set_config('app.is_superadmin', 'false', true)`);
30	}
